+function shouldSkipDefaultEncoding(value: unknown, def: $ZodDefaultDef, ctx: ParseContextInternal) {
+  const skipEncoding = def.skipEncoding;
+  if (!skipEncoding) return false;
+  if (typeof skipEncoding === "function") {
+    const result = skipEncoding(value);
+    if (result instanceof Promise && !ctx.async) {
+      throw new Error("Cannot use async skipEncoding in synchronous encode");
+    }
+    return result;
+  }
+  if (def.defaultValueIsFactory) {
+    const option = skipEncoding === true ? "true" : JSON.stringify(skipEncoding);
+    throw new Error(`Cannot use skipEncoding: ${option} with a factory default`);
+  }
+  const mode = skipEncoding === true ? "deep" : skipEncoding.mode;
+  return defaultValuesEqual(value, def.defaultValue, mode);
+}
+
+function defaultValuesEqual(a: unknown, b: unknown, mode: "strict" | "shallow" | "deep"): boolean {
+  if (mode === "strict" || Object.is(a, b)) return Object.is(a, b);
+  if (a instanceof Date || b instanceof Date) {
